import{_ as t,o as d,c as o,a3 as a}from"./chunks/framework.BTQ4eCVb.js";const u=JSON.parse('{"title":"Tenant API v1 — Attendance","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Attendance | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-attendance"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Attendance | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-attendance"}]]},"headers":[],"relativePath":"api/tenant-v1-attendance.md","filePath":"api/tenant-v1-attendance.md","lastUpdated":1788225865000}'),c={name:"api/tenant-v1-attendance.md"};function n(r,e,s,i,l,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="tenant-api-v1-—-attendance" tabindex="-1">Tenant API v1 — Attendance <a class="header-anchor" href="#tenant-api-v1-—-attendance" aria-label="Permalink to &quot;Tenant API v1 — Attendance&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>module:attendance</code>, plus <code>can:attendance.*</code>.</p><p>Catalog version: <strong>1.2.0</strong>.</p><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><h3 id="get-attendance-records-stats" tabindex="-1">GET <code>/attendance-records/stats</code> <a class="header-anchor" href="#get-attendance-records-stats" aria-label="Permalink to &quot;GET `/attendance-records/stats`&quot;">​</a></h3><p>Same filters as list (minus pagination/sort). Payload:</p><p><code>total</code>, <code>present</code>, <code>absent</code>, <code>half_day</code>, <code>remote</code>, <code>late</code>, plus open presence counts <code>checked_in_open</code>, <code>on_site_open</code>, <code>remote_open</code> (today, checked in, not checked out).</p><h2 id="today-self-check-in" tabindex="-1">Today / self check-in <a class="header-anchor" href="#today-self-check-in" aria-label="Permalink to &quot;Today / self check-in&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Permission</th></tr></thead><tbody><tr><td>GET</td><td><code>/attendance-records/today</code></td><td><code>attendance.view</code></td></tr><tr><td>POST</td><td><code>/attendance-records/check-in</code></td><td><code>attendance.create</code></td></tr><tr><td>POST</td><td><code>/attendance-records/check-out</code></td><td><code>attendance.update</code></td></tr></tbody></table><h3 id="get-attendance-records-today" tabindex="-1">GET <code>/attendance-records/today</code> <a class="header-anchor" href="#get-attendance-records-today" aria-label="Permalink to &quot;GET `/attendance-records/today`&quot;">​</a></h3><p>Returns today’s record for the linked employee (or <code>null</code>) plus <code>meta</code>:</p><ul><li><code>self_check_enabled</code>, <code>require_late_reason</code>, <code>timezone</code>, <code>today</code></li><li><code>thresholds.on_site</code> / <code>thresholds.remote</code> — <code>{ start, grace_minutes, is_late_now }</code></li></ul><h3 id="post-attendance-records-check-in" tabindex="-1">POST <code>/attendance-records/check-in</code> <a class="header-anchor" href="#post-attendance-records-check-in" aria-label="Permalink to &quot;POST `/attendance-records/check-in`&quot;">​</a></h3><p>Body: <code>work_mode</code> (<code>on_site</code>|<code>remote</code>), optional <code>reason_id</code> / <code>reason_notes</code>, optional <code>latitude</code> / <code>longitude</code>.</p><p>Late on-site uses office start + grace; late remote uses remote start + grace. When late and <code>attendance_require_late_reason</code> is on, <code>reason_id</code> is required; <strong>Other</strong> requires <code>reason_notes</code>. Status is <code>present</code>/<code>late</code> (on-site) or <code>remote</code>.</p><h3 id="post-attendance-records-check-out" tabindex="-1">POST <code>/attendance-records/check-out</code> <a class="header-anchor" href="#post-attendance-records-check-out" aria-label="Permalink to &quot;POST `/attendance-records/check-out`&quot;">​</a></h3><p>Body: optional <code>reason_id</code> / <code>reason_notes</code>, optional location. Check-out reason is optional; <strong>Other</strong> requires notes.</p><h2 id="attendance-reasons" tabindex="-1">Attendance reasons <a class="header-anchor" href="#attendance-reasons" aria-label="Permalink to &quot;Attendance reasons&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Permission</th></tr></thead><tbody><tr><td>GET</td><td><code>/attendance-reasons</code></td><td><code>attendance.view</code></td></tr><tr><td>POST</td><td><code>/attendance-reasons</code></td><td><code>attendance.update</code> (admin/owner catalog)</td></tr><tr><td>GET</td><td><code>/attendance-reasons/{attendanceReason}</code></td><td><code>attendance.view</code></td></tr><tr><td>PUT</td><td><code>/attendance-reasons/{attendanceReason}</code></td><td><code>attendance.update</code> (admin/owner)</td></tr><tr><td>DELETE</td><td><code>/attendance-reasons/{attendanceReason}</code></td><td><code>attendance.update</code> (admin/owner)</td></tr></tbody></table><p>Kinds: <code>check_in_late</code>, <code>check_out</code>. Each kind has a protected <strong>Other</strong> row (<code>is_other</code>).</p><h2 id="attendance-records-crud" tabindex="-1">Attendance records CRUD <a class="header-anchor" href="#attendance-records-crud" aria-label="Permalink to &quot;Attendance records CRUD&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Permission</th></tr></thead><tbody><tr><td>GET</td><td><code>/attendance-records</code></td><td><code>attendance.view</code></td></tr><tr><td>GET</td><td><code>/attendance-records/stats</code></td><td><code>attendance.view</code></td></tr><tr><td>POST</td><td><code>/attendance-records</code></td><td><code>attendance.create</code></td></tr><tr><td>GET</td><td><code>/attendance-records/{attendanceRecord}</code></td><td><code>attendance.view</code></td></tr><tr><td>PUT</td><td><code>/attendance-records/{attendanceRecord}</code></td><td><code>attendance.update</code></td></tr><tr><td>DELETE</td><td><code>/attendance-records/{attendanceRecord}</code></td><td><code>attendance.delete</code></td></tr><tr><td>POST</td><td><code>/attendance-records/{attendanceRecord}/restore</code></td><td><code>attendance.restore</code></td></tr><tr><td>DELETE</td><td><code>/attendance-records/{attendanceRecord}/force</code></td><td><code>attendance.force.delete</code></td></tr></tbody></table><h3 id="post-attendance-records" tabindex="-1">POST <code>/attendance-records</code> <a class="header-anchor" href="#post-attendance-records" aria-label="Permalink to &quot;POST `/attendance-records`&quot;">​</a></h3><p>Body: <code>employee_id</code>, <code>date</code> (required; unique per employee), optional <code>check_in</code> / <code>check_out</code> (<code>HH:MM</code> or <code>HH:MM:SS</code>), <code>status</code> (<code>present</code>|<code>absent</code>|<code>half_day</code>|<code>remote</code>|<code>late</code>, default <code>present</code>), <code>notes</code>.</p><p>Login side-effect (optional): when <code>attendance_auto_check_in_on_login</code> is <strong>true</strong>, successful <code>POST /auth/login</code> may upsert today’s on-site check-in for the user’s active linked employee. Default is <strong>false</strong> — staff must use check-in. If the login would be <strong>late</strong> and <code>attendance_require_late_reason</code> is <strong>true</strong>, auto check-in is <strong>skipped</strong> (no reason can be collected on login).</p><h3 id="put-attendance-records-attendancerecord" tabindex="-1">PUT <code>/attendance-records/{attendanceRecord}</code> <a class="header-anchor" href="#put-attendance-records-attendancerecord" aria-label="Permalink to &quot;PUT `/attendance-records/{attendanceRecord}`&quot;">​</a></h3><p>Partial update of the same fields (plus work mode / reason fields for managers).</p>',28)])])}const m=t(c,[["render",n]]);export{u as __pageData,m as default};
